/*Apollo Analytics tracker -- lightweight JavaScript tracking wrapper (window.ApolloTrack) that pushes analytics data to a wp-admin/admin-ajax.php endpoint and a local apolloAnalytics objec: .event() Sends custom event data to a WordPress AJAX endpoint; .pageview() Logs the current URL, page title, and referrer; .eventView() Tracks views for specific event IDs.*/window.ApolloTrack={event:function(e,n){window.apolloAnalytics&&window.apolloAnalytics.trackEvent&&window.apolloAnalytics.trackEvent(e,n),fetch(window.apolloAnalytics?.ajaxUrl||"/wp-admin/admin-ajax.php",{method:"POST",body:new URLSearchParams({action:"apollo_track_event",type:e,data:JSON.stringify(n),nonce:window.apolloAnalytics?.nonce||""}),keepalive:!0}).catch(function(){})},pageview:function(){this.event("pageview",{url:window.location.href,title:document.title,referrer:document.referrer})},eventView:function(e,n){this.event("event_view",{event_id:e,view_type:n||"page"})}};